#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    cin >> n;

    vector<int> prices(n);
    for (int i = 0; i < n; i++)
        cin >> prices[i];

    long long nextBuy = 0;
    long long nextHold = 0;

    for (int i = n - 1; i >= 0; i--) {
        long long curBuy = max(-prices[i] + nextHold, nextBuy);
        long long curHold = max(prices[i] + nextBuy, nextHold);

        nextBuy = curBuy;
        nextHold = curHold;
    }

    cout << nextBuy << '
';
    return 0;
}
